import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.CdvW4CUT.js";const g=JSON.parse('{"title":"Sales & billing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sales.md","filePath":"guide/sales.md","lastUpdated":1791960929000}'),i={name:"guide/sales.md"};function o(n,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="sales-billing" tabindex="-1">Sales &amp; billing <a class="header-anchor" href="#sales-billing" aria-label="Permalink to &quot;Sales &amp; billing&quot;">​</a></h1><p>Billing in SSPL Billing is done in <strong>two steps</strong>: the biller prepares the bill as a draft, and the cashier collects payment and submits it. This keeps the billing counter moving while payment is handled separately.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Biller: Sales Invoice  ──save draft──▶  Cashier Desk  ──collect &amp; submit──▶  Printed bill</span></span></code></pre></div><p>Small shops that bill and collect at the same counter can use <a href="#single-entry">Single Entry</a> instead.</p><h2 id="creating-a-bill" tabindex="-1">Creating a bill <a class="header-anchor" href="#creating-a-bill" aria-label="Permalink to &quot;Creating a bill&quot;">​</a></h2><ol><li>Open <strong>Sales Invoice</strong> from the Dashboard (or press <strong>F2</strong> for a new bill).</li><li>Choose the <strong>series</strong> (Page Up jumps to it). The series decides the price list, tax rate and print format.</li><li>Select the <strong>customer</strong>. Search by name, mobile number or code. Press the create option to add a new customer with address and GSTIN.</li><li>Add items: <ul><li>Scan the barcode, or type the item code and press <strong>Enter</strong>, or</li><li>Search by item name.</li></ul></li><li>Enter the <strong>quantity</strong>. Rate and discount fill in from the price list and discount rules; change them if you are allowed to.</li><li>Press <strong>End</strong> to jump to discount, then <strong>Ctrl+S</strong> or <strong>F8</strong> to save.</li></ol><p>The bill is now a <strong>draft</strong> and appears at the Cashier Desk. Stock is updated when the bill is saved.</p><div class="tip custom-block"><p class="custom-block-title">Customer history</p><p>While billing, you can view the customer&#39;s previous purchases and outstanding balance without leaving the screen.</p></div><h2 id="editing-or-deleting-a-draft" tabindex="-1">Editing or deleting a draft <a class="header-anchor" href="#editing-or-deleting-a-draft" aria-label="Permalink to &quot;Editing or deleting a draft&quot;">​</a></h2><p>Open the draft from the bill list, make changes and save again. Drafts can be deleted until the cashier submits them.</p><h2 id="single-entry" tabindex="-1">Single Entry <a class="header-anchor" href="#single-entry" aria-label="Permalink to &quot;Single Entry&quot;">​</a></h2><p>For counters where the same person bills and collects payment, <strong>Single Entry</strong> combines both steps into one screen.</p><h2 id="quotation" tabindex="-1">Quotation <a class="header-anchor" href="#quotation" aria-label="Permalink to &quot;Quotation&quot;">​</a></h2><p><strong>Quotation</strong> (Shift+F10) records a price offer for a customer without affecting stock. Convert it into a sales order or bill when the customer confirms.</p><h2 id="sales-order" tabindex="-1">Sales Order <a class="header-anchor" href="#sales-order" aria-label="Permalink to &quot;Sales Order&quot;">​</a></h2><p>Use <strong>Sales Order</strong> to book an order now and bill it later — for example, when goods are packed and dispatched over several days.</p><h2 id="catalogue" tabindex="-1">Catalogue <a class="header-anchor" href="#catalogue" aria-label="Permalink to &quot;Catalogue&quot;">​</a></h2><p><strong>Catalogue</strong> and <strong>Catalogue Viewer</strong> show items with images and stock, so customers can browse and build an order with the salesperson. The cart turns into an order or bill.</p><h2 id="customer-enquiry" tabindex="-1">Customer Enquiry <a class="header-anchor" href="#customer-enquiry" aria-label="Permalink to &quot;Customer Enquiry&quot;">​</a></h2><p>Record what a customer asked for that you didn&#39;t have in stock. Use it to plan purchases.</p><h2 id="corrections-after-submit" tabindex="-1">Corrections after submit <a class="header-anchor" href="#corrections-after-submit" aria-label="Permalink to &quot;Corrections after submit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Screen</th></tr></thead><tbody><tr><td>Cancel a submitted bill</td><td><strong>Cancellation</strong> — stock, ledger and incentive entries are reversed automatically</td></tr><tr><td>Change the date of a submitted bill</td><td><strong>Modify Submitted</strong></td></tr></tbody></table><p>Both screens are normally limited to supervisors.</p>',23)])])}const p=t(i,[["render",o]]);export{g as __pageData,p as default};
